class_name Synty extends Object
## Helpers for the POLYGON Mech Pack assets (labs/mech/assets/synty).
## FBX materials reference textures by path that does not exist here, so we
## re-bind the shared palette texture onto every surface (UVs stay correct).

const DIR := "res://assets/synty/"


static func asset_path(file: String) -> String:
	return DIR + file


static func has_asset(file: String) -> bool:
	return ResourceLoader.exists(asset_path(file))


static func load_scene(file: String) -> PackedScene:
	var path := asset_path(file)
	if not ResourceLoader.exists(path):
		return null
	var res := ResourceLoader.load(path)
	return res as PackedScene


static func load_texture(file: String) -> Texture2D:
	var path := asset_path(file)
	if not ResourceLoader.exists(path):
		return null
	return ResourceLoader.load(path) as Texture2D


## Instantiate an FBX scene, hide variant parts, bind the palette, and
## (optionally) scale so the model stands `target_h` tall with feet at y=0.
## stand_up: model is authored Z-up (lying on its back) - rotate into Y-up.
static func instance(file: String, target_h := 0.0, hide_re := "",
		stand_up := false) -> Node3D:
	var ps: PackedScene = load_scene(file)
	if ps == null:
		return null
	var inst := ps.instantiate() as Node3D
	var re: RegEx = null
	if hide_re != "":
		re = RegEx.new()
		re.compile(hide_re)
	for mi in inst.find_children("*", "MeshInstance3D", true, false):
		var m := mi as MeshInstance3D
		if re != null and re.search(m.name) != null:
			m.visible = false
			continue
		_bind_palette(m)
	if stand_up:
		inst.rotation_degrees = Vector3(0, 180, 0)   # yaw only: model is Y-up
	var wrap := Node3D.new()
	wrap.add_child(inst)
	if target_h > 0.0:
		var aabb := fitted_aabb(wrap)
		if aabb.size.y > 0.01:
			var s := target_h / aabb.size.y
			wrap.scale = Vector3.ONE * s
			wrap.position = Vector3(0, -aabb.position.y * s, 0)
	return wrap


static func _bind_palette(m: MeshInstance3D) -> void:
	var palette: Texture2D = load_texture("palette_a.png")
	if palette == null or m.mesh == null:
		return
	for i in range(m.mesh.get_surface_count()):
		var mat := m.get_active_material(i)
		var std := mat as StandardMaterial3D
		if std == null:
			std = StandardMaterial3D.new()
			if mat != null:
				std.albedo_color = (mat as BaseMaterial3D).albedo_color \
						if mat is BaseMaterial3D else Color.WHITE
		std.albedo_texture = palette
		m.set_surface_override_material(i, std)


## World-space AABB of every visible mesh under `n` (approximate for skinned
## meshes: bind-pose mesh AABB transformed by the node chain).
static func fitted_aabb(n: Node3D) -> AABB:
	var box := AABB()
	var first := true
	for mi in n.find_children("*", "MeshInstance3D", true, false):
		var m := mi as MeshInstance3D
		if not m.visible or m.mesh == null:
			continue
		var rel := m.transform * m.mesh.get_aabb()
		var p := m.get_parent()
		while p != null and p is Node3D and p != n:
			rel = (p as Node3D).transform * rel
			p = p.get_parent()
		if first:
			box = rel
			first = false
		else:
			box = box.merge(rel)
	return box


## UAL clip bone names -> Synty MechPack characters.fbx bone names.
## Tracks without a mapping (ring/pinky fingers, leaf tips) are dropped.
const BONE_MAP := {
	"pelvis": "Hips",
	"neck_01": "Neck",
	"upperarm_l": "Shoulder_L", "upperarm_r": "Shoulder_R",
	"lowerarm_l": "Elbow_L", "lowerarm_r": "Elbow_R",
	"thigh_l": "UpperLeg_L", "thigh_r": "UpperLeg_R",
	"calf_l": "LowerLeg_L", "calf_r": "LowerLeg_R",
	"foot_l": "Ankle_L", "foot_r": "Ankle_R",
	"thumb_01_l": "Thumb_01_L", "thumb_02_l": "Thumb_02_L", "thumb_03_l": "Thumb_03_L",
	"thumb_01_r": "Thumb_01_2", "thumb_02_r": "Thumb_02_2", "thumb_03_r": "Thumb_03_2",
	"index_01_l": "IndexFinger_01_L", "index_02_l": "IndexFinger_02_L",
	"index_03_l": "IndexFinger_03_L",
	"index_01_r": "IndexFinger_01_2", "index_02_r": "IndexFinger_02_2",
	"index_03_r": "IndexFinger_03_2",
	"middle_01_l": "Finger_01_L", "middle_02_l": "Finger_02_L",
	"middle_03_l": "Finger_03_L",
	"middle_01_r": "Finger_01_2", "middle_02_r": "Finger_02_2",
	"middle_03_r": "Finger_03_2",
}


## Copy all animations from one AnimationPlayer into another. Handles:
## - UAL "Armature/Skeleton3D" track root -> our plain "Skeleton3D"
## - bone renaming via BONE_MAP (FBX vs GLB naming)
## - rest-pose retarget: rotation keys are compensated by
##   q_dst_rest * q_src_rest^-1 so clips authored on the UAL rest play
##   correctly on the FBX rest (without this the body tips horizontal).
## Unmapped tracks (fingers etc.) and position/scale tracks are dropped.
static func transfer_animations(from_player: AnimationPlayer,
		to_player: AnimationPlayer) -> int:
	var lib: AnimationLibrary
	if to_player.has_animation_library(""):
		lib = to_player.get_animation_library("")
	else:
		lib = AnimationLibrary.new()
		to_player.add_animation_library("", lib)
	var src_skel: Skeleton3D = null
	var dst_skel: Skeleton3D = null
	for s in from_player.get_node(from_player.root_node) \
			.find_children("*", "Skeleton3D", true, false):
		src_skel = s
	for s in to_player.get_node(to_player.root_node) \
			.find_children("*", "Skeleton3D", true, false):
		dst_skel = s
	var valid := {}
	if dst_skel != null:
		for b in range(dst_skel.get_bone_count()):
			valid[dst_skel.get_bone_name(b).to_lower()] = true

	# Per-source-bone retarget delta: q_delta = q_dst_rest * q_src_rest^-1.
	var delta := {}   # ual bone name (lower) -> Quaternion
	if src_skel != null and dst_skel != null:
		for sub_l in BONE_MAP:
			var src_idx := src_skel.find_bone(String(sub_l))
			var dst_name: String = BONE_MAP[sub_l]
			var dst_idx := dst_skel.find_bone(dst_name)
			if src_idx >= 0 and dst_idx >= 0:
				var q_src := src_skel.get_bone_rest(src_idx).basis.get_rotation_quaternion()
				var q_dst := dst_skel.get_bone_rest(dst_idx).basis.get_rotation_quaternion()
				delta[sub_l] = q_dst * q_src.inverse()

	var n := 0
	for anim_name in from_player.get_animation_list():
		if lib.has_animation(anim_name):
			continue
		var anim := (from_player.get_animation(anim_name) as Animation).duplicate()
		for t in range(anim.get_track_count() - 1, -1, -1):
			var tt: int = anim.track_get_type(t)
			var p := String(anim.track_get_path(t))
			var parts := p.split(":")
			if parts.size() < 2:
				anim.remove_track(t)
				continue
			var sub_l := parts[parts.size() - 1].to_lower()
			var new_sub: String = parts[parts.size() - 1]
			if BONE_MAP.has(sub_l):
				new_sub = BONE_MAP[sub_l]
			if valid.size() > 0 and not valid.has(new_sub.to_lower()):
				anim.remove_track(t)
				continue
			# Position/scale tracks assume the UAL rest skeleton - dropped so
			# our rest heights hold (body stays upright).
			if tt == Animation.TYPE_POSITION_3D or tt == Animation.TYPE_SCALE_3D:
				anim.remove_track(t)
				continue
			# Strip the UAL "Armature/" root so the track binds to our skeleton.
			var node_part := parts[0]
			if node_part.begins_with("Armature/"):
				node_part = node_part.substr("Armature/".length())
			if new_sub != parts[parts.size() - 1] or node_part != parts[0]:
				parts[0] = node_part
				parts[parts.size() - 1] = new_sub
				anim.track_set_path(t, ":".join(parts))
			# Rest-pose compensation on rotation keys (4.7: generic accessors).
			if tt == Animation.TYPE_ROTATION_3D and delta.has(sub_l):
				var qd: Quaternion = delta[sub_l]
				for k in range(anim.track_get_key_count(t)):
					var kt: float = anim.track_get_key_time(t, k)
					var qv: Quaternion = anim.track_get_key_value(t, k)
					anim.track_set_key_value(t, k, qd * qv)
		if anim.get_track_count() > 0:
			lib.add_animation(anim_name, anim)
			n += 1
	return n


## Extract one mesh from a multi-mesh FBX (e.g. one pilot out of Characters).
static func extract_mesh(file: String, name_hint: String) -> MeshInstance3D:
	var ps: PackedScene = load_scene(file)
	if ps == null:
		return null
	var inst := ps.instantiate()
	var found: MeshInstance3D = null
	for mi in inst.find_children("*", "MeshInstance3D", true, false):
		if name_hint == "" or (mi as MeshInstance3D).name.findn(name_hint) >= 0:
			found = (mi as MeshInstance3D).duplicate()
			break
	inst.free()
	if found != null:
		_bind_palette(found)
	return found

extends RefCounted
## Loads and validates a mission config Dictionary (see data/*.json).
## The kernel itself only requires the sections below; hosts may carry extra
## sections (e.g. "roles" combat stats) that the kernel ignores.

const REQUIRED_TOP := ["meta", "timing", "core", "extraction", "risk", "waves"]
const PROFILE_REQUIRED := ["id", "ex_rate_mul", "mods"]
const WAVE_REQUIRED := ["index", "name", "duration_steps", "lanes", "spawn_table"]


static func load_json(path: String) -> Dictionary:
	var f := FileAccess.open(path, FileAccess.READ)
	if f == null:
		return {}
	var parsed: Variant = JSON.parse_string(f.get_as_text())
	if typeof(parsed) != TYPE_DICTIONARY:
		return {}
	return parsed


static func validate(cfg: Dictionary) -> Array:
	var errors: Array = []
	for key in REQUIRED_TOP:
		if not cfg.has(key):
			errors.append("missing top-level key '%s'" % key)
	if not errors.is_empty():
		return errors

	for w in cfg.waves:
		for key in WAVE_REQUIRED:
			if not w.has(key):
				errors.append("wave missing '%s'" % key)
		if w.has("spawn_table") and typeof(w.spawn_table) != TYPE_ARRAY:
			errors.append("wave %s spawn_table must be array" % str(w.get("index")))
		for s in w.get("spawn_table", []):
			for key in ["at_step", "lane", "role", "count"]:
				if not s.has(key):
					errors.append("wave %s spawn entry missing '%s'" % [str(w.get("index")), key])

	var profiles: Array = cfg.risk.get("profiles", [])
	if profiles.is_empty():
		errors.append("risk.profiles empty")
	var ids: Array = []
	for p in profiles:
		for key in PROFILE_REQUIRED:
			if not p.has(key):
				errors.append("profile missing '%s'" % key)
		ids.append(p.get("id"))
	var default_id: String = cfg.risk.get("default_profile", "")
	if default_id != "" and not ids.has(default_id):
		errors.append("default_profile '%s' not in profiles" % default_id)

	var ex: Dictionary = cfg.extraction
	if int(ex.get("quota_mex", 0)) <= 0:
		errors.append("extraction.quota_mex must be > 0")
	if float(cfg.timing.get("fixed_step_ms", 0)) <= 0.0:
		errors.append("timing.fixed_step_ms must be > 0")
	if int(cfg.core.get("hp", 0)) <= 0:
		errors.append("core.hp must be > 0")

	# --- VS3-T4 hardening: fields the kernel reads unguarded + structural sanity.
	if float(ex.get("base_rate_mex_per_step", 0)) <= 0.0:
		errors.append("extraction.base_rate_mex_per_step must be > 0")
	if int(ex.get("extract_duration_steps", 0)) <= 0:
		errors.append("extraction.extract_duration_steps must be > 0")
	var frac: float = float(cfg.core.get("critical_threshold_frac", -1.0))
	if frac <= 0.0 or frac >= 1.0:
		errors.append("core.critical_threshold_frac must be in (0, 1)")
	var meta: Dictionary = cfg.get("meta", {})
	if str(meta.get("id", "")).is_empty():
		errors.append("meta.id must not be empty")
	if int(meta.get("seed", -1)) < 0:
		errors.append("meta.seed must be >= 0")

	var seen_idx := {}
	for w2 in cfg.waves:
		var idx := int(w2.get("index", -1))
		if seen_idx.has(idx):
			errors.append("duplicate wave index %d" % idx)
		seen_idx[idx] = true
		if int(w2.get("duration_steps", 0)) <= 0:
			errors.append("wave %d duration_steps must be > 0" % idx)
		var lanes_v: Variant = w2.get("lanes", [])
		if typeof(lanes_v) != TYPE_ARRAY or (lanes_v as Array).is_empty():
			errors.append("wave %d lanes must be a non-empty array" % idx)
		for s2 in w2.get("spawn_table", []):
			if int(s2.get("at_step", -1)) < 0:
				errors.append("wave %d spawn entry at_step must be >= 0" % idx)
			if int(s2.get("count", 0)) <= 0:
				errors.append("wave %d spawn entry count must be > 0" % idx)
	return errors


static func profile_by_id(cfg: Dictionary, id: String) -> Dictionary:
	for p in cfg.risk.profiles:
		if p.id == id:
			return p
	return {}

extends RefCounted
## HARVEST mission kernel — deterministic, presentation-independent operation core.
##
## Consumes gameplay reports (commands), emits authoritative facts (events).
## Knows nothing about UI, networking, Steam, 3D maps, enemy AI, models or audio.
## A host process feeds commands and consumes SPAWN_INTENT / WaveIntent packets;
## time moves ONLY through advance(), so identical command streams + seed give
## byte-identical telemetry digests.

const Defs := preload("res://mission/defs.gd")
const Planner := preload("res://mission/wave_planner.gd")
const Config := preload("res://mission/mission_config.gd")
const Telemetry := preload("res://mission/telemetry.gd")

signal event_emitted(e: Dictionary)

var telemetry := Telemetry.new()

var cfg: Dictionary = {}
var step: int = 0
var phase: String = Defs.BOOT
var risk_id: String = ""
var outcome: Dictionary = {}            # {} until terminal, else {"outcome","reason"}
## VS3-T1: fractional-seconds carry so real-loop callers feeding advance(0.016)
## at 60 fps still cross a 100 ms step boundary (960 ms of debt -> 1 step).
var _step_debt_ms: float = 0.0

var core_hp: int = 0
var core_max_hp: int = 0
var core_critical_fired: bool = false

var ex_mex: int = 0                      # extracted value, milli-EX (integer math only)
var quota_met: bool = false

var waves: Array = []                    # sorted wave defs
var wave_cursor: int = 0                 # next wave to start
var waves_completed: int = 0
var plan: Dictionary = {}                # active WavePlan (ASSAULT) or {}
var unresolved: Dictionary = {}          # batch_id -> emitted-but-unresolved intent
var final_lull: bool = false             # all waves done, waiting for withdrawal

var withdrawal_end_step: int = 0
var extraction_timing: String = "NONE"   # EARLY | FULL | NONE

var assets: Dictionary = {}              # asset_id -> {"type", "alive"}
var ammo_consumed: int = 0
var ammo_resupplied: int = 0

var _seed: int = 1
var _pending_ex_delta: int = 0


func configure(mission_cfg: Dictionary) -> Dictionary:
	if phase != Defs.BOOT:
		return _reject(Defs.CMD_CONFIGURE, "ALREADY_CONFIGURED")
	var errors: Array = Config.validate(mission_cfg)
	if not errors.is_empty():
		return _reject(Defs.CMD_CONFIGURE, "INVALID_CONFIG:%s" % str(errors))
	cfg = mission_config_duped(mission_cfg)
	waves = cfg.waves.duplicate(true)
	waves.sort_custom(func(a, b): return int(a.index) < int(b.index))
	core_max_hp = int(cfg.core.hp)
	core_hp = core_max_hp
	risk_id = str(cfg.risk.default_profile)
	_seed = int(cfg.meta.get("seed", 1))
	transition_to(Defs.SCOUT)
	_emit(Defs.EV_CONFIGURED, {
		"mission": str(cfg.meta.get("id", "")),
		"config_version": int(cfg.meta.get("version", 0)),
		"seed": _seed,
		"quota_mex": int(cfg.extraction.quota_mex),
		"core_hp": core_max_hp,
		"risk_profiles": cfg.risk.profiles.map(func(p): return p.id),
	})
	return {"accepted": true}


# ------------------------------------------------------------------ commands

func cmd(id: String, payload: Dictionary = {}) -> Dictionary:
	match id:
		Defs.CMD_SET_RISK:
			return _cmd_set_risk(str(payload.get("mode", "")))
		Defs.CMD_START_WAVE:
			return _cmd_start_wave()
		Defs.CMD_REQUEST_WITHDRAWAL:
			return _cmd_request_withdrawal()
		Defs.CMD_CORE_DAMAGE:
			return _cmd_core_damage(int(payload.get("amount", 0)), str(payload.get("source", "")))
		Defs.CMD_BATCH_RESOLVED:
			return _cmd_batch_resolved(str(payload.get("batch_id", "")))
		Defs.CMD_AMMO_SPENT:
			return _cmd_amount(id, int(payload.get("amount", 0)), func(n): ammo_consumed += n)
		Defs.CMD_RESUPPLY:
			return _cmd_amount(id, int(payload.get("amount", 0)), func(n): ammo_resupplied += n)
		Defs.CMD_EX_CREDIT:
			return _cmd_ex_credit(int(payload.get("amount", 0)))
		Defs.CMD_ASSET_REGISTERED:
			return _cmd_asset_registered(str(payload.get("asset_id", "")), str(payload.get("type", "")))
		Defs.CMD_ASSET_LOST:
			return _cmd_asset_lost(str(payload.get("asset_id", "")))
		Defs.CMD_HAZARD_REPORT:
			if phase == Defs.CONCLUDED:
				return _reject(id, "OPERATION_CONCLUDED")
			_emit(Defs.EV_HAZARD, {"hazard_id": payload.get("hazard_id", ""), "source": "HOST"})
			return {"accepted": true}
		Defs.CMD_REPORT_METRIC:
			return _cmd_report_metric(str(payload.get("key", "")), payload.get("value"))
		_:
			return _reject(id, "UNKNOWN_COMMAND")


## The only clock. Deterministic fixed-step processing.
func advance(seconds: float) -> void:
	if phase == Defs.BOOT or phase == Defs.CONCLUDED:
		return
	var step_ms: float = float(cfg.timing.fixed_step_ms)
	# VS3-T1: accumulate fractional time instead of rounding per call —
	# round(0.016s * 1000 / 100) == 0 stalled the mission clock at 60 fps.
	_step_debt_ms += maxf(0.0, seconds * 1000.0)
	var steps := int(floor(_step_debt_ms / step_ms))
	_step_debt_ms -= steps * step_ms
	for i in steps:
		_do_step()
	_flush_ex_tick()


func state() -> Dictionary:
	var p := plan
	return {
		"phase": phase,
		"step": step,
		"risk_id": risk_id,
		"core_hp": core_hp,
		"core_max_hp": core_max_hp,
		"ex_mex": ex_mex,
		"quota_mex": int(cfg.get("extraction", {}).get("quota_mex", 0)),
		"quota_met": quota_met,
		"waves_completed": waves_completed,
		"waves_total": waves.size(),
		"current_wave_index": int(p.get("wave_index", 0)),
		"unresolved_batches": unresolved.size(),
		"final_lull": final_lull,
		"outcome": outcome.duplicate(true),
		"kpis": kpis(),
	}


## Public: defensive copy. Kernel internals use _live_profile() instead.
func current_profile() -> Dictionary:
	return Config.profile_by_id(cfg, risk_id).duplicate(true)


func _live_profile() -> Dictionary:
	for p in cfg.risk.profiles:
		if p.id == risk_id:
			return p
	return {}


func get_plan() -> Dictionary:
	return plan.duplicate(true)


func kpis() -> Dictionary:
	var registered := assets.size()
	var alive := 0
	for a in assets.values():
		if a.alive:
			alive += 1
	var success: bool = not outcome.is_empty() and outcome.outcome == "SUCCESS"
	var timing := extraction_timing
	if not success:
		timing = "NONE"
	return {
		"core_survived": core_hp > 0,
		"ex_extracted_mex": ex_mex,
		"payout_proxy_mex": ex_mex,
		"asset_preservation_frac": (float(alive) / registered) if registered > 0 else 1.0,
		"assets_registered": registered,
		"assets_lost": registered - alive,
		"ammo_consumed": ammo_consumed,
		"ammo_resupplied": ammo_resupplied,
		"ex_per_ammo_point": snappedf(float(ex_mex) / maxf(1.0, float(ammo_consumed)), 0.001),
		"contract_completed": success,
		"extraction_timing": timing,
		"waves_completed": waves_completed,
		"waves_total": waves.size(),
		"duration_steps": step,
	}


# ----------------------------------------------------------------- internals

func _do_step() -> void:
	step += 1
	match phase:
		Defs.ASSAULT:
			_tick_assault()
		Defs.WITHDRAWAL:
			if step >= withdrawal_end_step:
				_resolve_success()


func _tick_assault() -> void:
	_accrue_extraction()
	for b in Planner.due_batches(plan, step):
		unresolved[b.batch_id] = b.duplicate(true)
		_emit(Defs.EV_SPAWN_INTENT, {
			"batch_id": b.batch_id, "lane": b.lane, "role": b.role,
			"count": b.count, "aggression": plan.aggression,
		})
	for hz in plan.hazards:
		if int(hz.at_step) == step:
			_emit(Defs.EV_HAZARD, {"hazard_id": hz.hazard_id, "source": "PLAN"})
	_check_wave_completion()


func _accrue_extraction() -> void:
	var base_rate: float = float(cfg.extraction.base_rate_mex_per_step)
	var rate := int(round(base_rate * float(_live_profile().ex_rate_mul)))
	if rate <= 0:
		return
	_apply_ex(rate)


func _apply_ex(amount_mex: int) -> void:
	ex_mex += amount_mex
	_pending_ex_delta += amount_mex
	if not quota_met and ex_mex >= int(cfg.extraction.quota_mex):
		quota_met = true
		_emit(Defs.EV_CONTRACT_READY, {"extracted_mex": ex_mex, "quota_mex": int(cfg.extraction.quota_mex)})


func _flush_ex_tick() -> void:
	if _pending_ex_delta != 0:
		_emit(Defs.EV_EX_TICK, {"delta_mex": _pending_ex_delta, "total_mex": ex_mex})
		_pending_ex_delta = 0


func _check_wave_completion() -> void:
	if step < int(plan.end_step) or not unresolved.is_empty():
		return
	waves_completed = maxi(waves_completed, int(plan.wave_index))
	_emit(Defs.EV_WAVE_COMPLETED, {"wave_index": plan.wave_index, "at_step": step})
	plan = {}
	unresolved.clear()

	var more_waves := wave_cursor < waves.size()
	if more_waves:
		transition_to(Defs.INTERMISSION)
		_emit(Defs.EV_RESUPPLY_WINDOW_OPENED, {"until": "START_WAVE"})
		var provisional := Planner.plan_wave(waves[wave_cursor], _live_profile(), _seed, step + 1, 0)
		_emit(Defs.EV_THREAT_PREVIEW, Planner.preview_from_plan(provisional))
	elif not quota_met:
		_resolve_failure("QUOTA_UNMET")
	else:
		final_lull = true
		transition_to(Defs.INTERMISSION)


func _replan_current_wave(new_profile: Dictionary) -> void:
	if plan.is_empty():
		return
	var wave_def: Dictionary = waves[wave_cursor - 1]
	plan = Planner.retime_pending(plan, wave_def, new_profile, step)
	_emit(Defs.EV_WAVE_REPLANNED, {
		"wave_index": plan.wave_index,
		"plan_hash": plan.plan_hash,
		"pending_batches": plan.batches.size(),
		"cadence_mul": plan.get("cadence_mul", 1.0),
	})


func _resolve_success() -> void:
	extraction_timing = "EARLY" if waves_completed < waves.size() else "FULL"
	outcome = {"outcome": "SUCCESS", "reason": "EXTRACTED"}
	transition_to(Defs.CONCLUDED)
	_emit_resolved()


func _resolve_failure(reason: String) -> void:
	outcome = {"outcome": "FAILURE", "reason": reason}
	transition_to(Defs.CONCLUDED)
	_emit_resolved()


func _emit_resolved() -> void:
	var payload := {"kpis": kpis()}
	payload.merge(outcome, true)
	_emit(Defs.EV_RESOLVED, payload)


func transition_to(to: String) -> void:
	var from := phase
	phase = to
	_emit(Defs.EV_PHASE, {"from": from, "to": to})


func _emit(kind: String, data: Dictionary = {}) -> void:
	data["step"] = step
	data["phase"] = phase
	var e := telemetry.log(kind, data)
	event_emitted.emit(e)


func _reject(id: String, reason: String) -> Dictionary:
	if phase != Defs.BOOT:
		_emit(Defs.EV_REJECTED, {"command": id, "reason": reason})
	return {"accepted": false, "reason": reason}


# ------------------------------------------------------------- command bodies

func _cmd_set_risk(mode: String) -> Dictionary:
	if phase == Defs.CONCLUDED:
		return _reject(Defs.CMD_SET_RISK, "OPERATION_CONCLUDED")
	if phase == Defs.WITHDRAWAL:
		return _reject(Defs.CMD_SET_RISK, "LOCKED_DURING_EXTRACTION")
	if phase != Defs.SCOUT and phase != Defs.INTERMISSION and phase != Defs.ASSAULT:
		return _reject(Defs.CMD_SET_RISK, "BAD_PHASE")
	if mode == risk_id:
		return _reject(Defs.CMD_SET_RISK, "SAME_MODE")
	var prof := Config.profile_by_id(cfg, mode)
	if prof.is_empty():
		return _reject(Defs.CMD_SET_RISK, "UNKNOWN_PROFILE")
	var from_id := risk_id
	risk_id = mode
	var effective := "IMMEDIATE"
	if phase == Defs.ASSAULT:
		if not bool(cfg.risk.get("allow_midwave_switch", true)):
			risk_id = from_id
			return _reject(Defs.CMD_SET_RISK, "MIDWAVE_SWITCH_DISABLED")
		_replan_current_wave(_live_profile())
		effective = "REPLANNED_MIDWAVE"
	_emit(Defs.EV_RISK, {"from": from_id, "to": mode, "effective": effective})
	return {"accepted": true}


func _cmd_start_wave() -> Dictionary:
	if phase == Defs.SCOUT or phase == Defs.INTERMISSION:
		if wave_cursor >= waves.size():
			return _reject(Defs.CMD_START_WAVE, "NO_WAVES_REMAINING")
		var wave_def: Dictionary = waves[wave_cursor]
		wave_cursor += 1
		plan = Planner.plan_wave(wave_def, _live_profile(), _seed, step + 1, 0)
		transition_to(Defs.ASSAULT)
		_emit(Defs.EV_WAVE_PLANNED, {"plan_hash": plan.plan_hash, "wave_index": plan.wave_index,
			"lanes": plan.lanes, "aggression": plan.aggression, "intel_quality": plan.intel_quality,
			"batch_count": plan.batches.size()})
		_emit(Defs.EV_WAVE_STARTED, {"wave_index": plan.wave_index, "name": plan.wave_name})
		return {"accepted": true}
	if phase == Defs.CONCLUDED:
		return _reject(Defs.CMD_START_WAVE, "OPERATION_CONCLUDED")
	return _reject(Defs.CMD_START_WAVE, "BAD_PHASE")


func _cmd_request_withdrawal() -> Dictionary:
	if phase == Defs.CONCLUDED:
		return _reject(Defs.CMD_REQUEST_WITHDRAWAL, "OPERATION_CONCLUDED")
	if phase != Defs.ASSAULT and phase != Defs.INTERMISSION:
		return _reject(Defs.CMD_REQUEST_WITHDRAWAL, "BAD_PHASE")
	if not quota_met:
		return _reject(Defs.CMD_REQUEST_WITHDRAWAL, "QUOTA_NOT_MET")
	withdrawal_end_step = step + int(cfg.extraction.extract_duration_steps)
	transition_to(Defs.WITHDRAWAL)
	_emit(Defs.EV_WITHDRAWAL_STARTED, {"ends_at_step": withdrawal_end_step,
		"waves_completed": waves_completed})
	return {"accepted": true}


func _cmd_core_damage(amount: int, source: String) -> Dictionary:
	if phase == Defs.CONCLUDED:
		return _reject(Defs.CMD_CORE_DAMAGE, "OPERATION_CONCLUDED")
	if amount <= 0:
		return _reject(Defs.CMD_CORE_DAMAGE, "NON_POSITIVE_AMOUNT")
	if core_hp <= 0:
		return _reject(Defs.CMD_CORE_DAMAGE, "CORE_ALREADY_DESTROYED")
	core_hp = maxi(0, core_hp - amount)
	_emit(Defs.EV_CORE_DAMAGED, {"amount": amount, "hp_left": core_hp, "source": source})
	var threshold := int(round(core_max_hp * float(cfg.core.get("critical_threshold_frac", 0.25))))
	if core_hp <= threshold and not core_critical_fired and core_hp > 0:
		core_critical_fired = true
		_emit(Defs.EV_CORE_CRITICAL, {"hp_left": core_hp})
	if core_hp <= 0:
		_emit(Defs.EV_CORE_DESTROYED, {})
		plan = {}
		_resolve_failure("CORE_DESTROYED")
	return {"accepted": true}


func _cmd_batch_resolved(batch_id: String) -> Dictionary:
	if phase == Defs.CONCLUDED:
		return _reject(Defs.CMD_BATCH_RESOLVED, "OPERATION_CONCLUDED")
	if not unresolved.has(batch_id):
		return _reject(Defs.CMD_BATCH_RESOLVED, "UNKNOWN_BATCH")
	unresolved.erase(batch_id)
	return {"accepted": true}


func _cmd_amount(id: String, amount: int, apply: Callable) -> Dictionary:
	if phase == Defs.CONCLUDED:
		return _reject(id, "OPERATION_CONCLUDED")
	if amount <= 0:
		return _reject(id, "NON_POSITIVE_AMOUNT")
	apply.call(amount)
	return {"accepted": true}


func _cmd_ex_credit(amount: int) -> Dictionary:
	if phase == Defs.CONCLUDED:
		return _reject(Defs.CMD_EX_CREDIT, "OPERATION_CONCLUDED")
	if amount <= 0:
		return _reject(Defs.CMD_EX_CREDIT, "NON_POSITIVE_AMOUNT")
	_apply_ex(amount)
	return {"accepted": true}


func _cmd_report_metric(key: String, value) -> Dictionary:
	if phase == Defs.CONCLUDED:
		return _reject(Defs.CMD_REPORT_METRIC, "OPERATION_CONCLUDED")
	if key == "":
		return _reject(Defs.CMD_REPORT_METRIC, "EMPTY_KEY")
	_emit(Defs.EV_METRIC, {"key": key, "value": value})
	return {"accepted": true}


func _cmd_asset_registered(asset_id: String, type: String) -> Dictionary:
	if phase == Defs.CONCLUDED:
		return _reject(Defs.CMD_ASSET_REGISTERED, "OPERATION_CONCLUDED")
	if asset_id == "":
		return _reject(Defs.CMD_ASSET_REGISTERED, "EMPTY_ID")
	if assets.has(asset_id):
		return _reject(Defs.CMD_ASSET_REGISTERED, "DUPLICATE_ID")
	assets[asset_id] = {"type": type, "alive": true}
	return {"accepted": true}


func _cmd_asset_lost(asset_id: String) -> Dictionary:
	if phase == Defs.CONCLUDED:
		return _reject(Defs.CMD_ASSET_LOST, "OPERATION_CONCLUDED")
	if not assets.has(asset_id):
		return _reject(Defs.CMD_ASSET_LOST, "UNKNOWN_ASSET")
	if not assets[asset_id].alive:
		return _reject(Defs.CMD_ASSET_LOST, "ALREADY_LOST")
	assets[asset_id].alive = false
	return {"accepted": true}


## Deep-duplicate so hosts cannot mutate live kernel state through the config ref.
