class_name MissionLoader
extends RefCounted

## Loads the canonical mission JSON (ADR-10, wave step 3) and applies the
## project seed rule: an explicit CLI --seed=N overrides meta.seed; otherwise
## the config's own deterministic seed is used. The effective seed must be
## echoed into the log identity header by whoever configures the kernel.

const DEFAULT_PATH := "res://data/missions/mission_default.json"


static func load_canonical(path: String = DEFAULT_PATH) -> Dictionary:
	var mc: Resource = load("res://mission/mission_config.gd")
	if mc == null:
		push_error("MissionLoader: mission_config script missing")
		return {}
	var cfg: Dictionary = mc.load_json(path)
	if cfg.is_empty():
		push_error("MissionLoader: cannot load/parse %s" % path)
		return {}
	if Session.seed_explicit and cfg.has("meta") and cfg.meta is Dictionary:
		cfg["meta"]["seed"] = Session.seed_value
	var problems: Array = mc.validate(cfg)
	if not problems.is_empty():
		for p in problems:
			push_error("MissionLoader: %s" % str(p))
		return {}
	return cfg


static func effective_seed(cfg: Dictionary) -> int:
	if Session.seed_explicit:
		return Session.seed_value
	return int(cfg.get("meta", {}).get("seed", Session.DEFAULT_SEED))

extends RefCounted
## Append-only machine-readable event log. JSONL dump + replay digest.

signal appended(e: Dictionary)

var events: Array = []


func log(kind: String, data: Dictionary = {}) -> Dictionary:
	var e := {"kind": kind}
	e.merge(data, true)
	appended.emit(e)
	# store a private copy so listeners cannot rewrite history (digest safety)
	events.append(e.duplicate(true))
	return e


func dump_jsonl(path: String) -> bool:
	DirAccess.make_dir_recursive_absolute(path.get_base_dir())
	var f := FileAccess.open(path, FileAccess.WRITE)
	if f == null:
		return false
	for e in events:
		f.store_line(JSON.stringify(e, "", true, true))
	f.close()
	return true


## Canonical digest of the whole stream - equal digests mean identical runs.
func digest() -> String:
	var parts := PackedStringArray()
	for e in events:
		parts.append(JSON.stringify(e, "", true, true))
	return "\n".join(parts).sha256_text()


func count_kind(kind: String) -> int:
	var n := 0
	for e in events:
		if e.kind == kind:
			n += 1
	return n


func last_of_kind(kind: String) -> Dictionary:
	for i in range(events.size() - 1, -1, -1):
		if events[i].kind == kind:
			return events[i]
	return {}

class_name WavePlanner
extends RefCounted
## Pure wave planner: (wave_def x risk_profile x seed) -> WavePlan.
## No kernel state, no time, no I/O. Same inputs always give the same plan.
##
## A plan is the full authoritative schedule for a wave under the *current*
## risk profile. Mid-wave risk changes replan only the not-yet-due remainder;
## batches already emitted as SPAWN_INTENT are immutable.

const Defs := preload("res://mission/defs.gd")


## Collapse a profile's mods list into effective scalar hooks.
static func effective_hooks(profile: Dictionary) -> Dictionary:
	var h := {
		"cadence_mul": 1.0,
		"count_mul": 1.0,
		"aggression_mul": 1.0,
		"hazard_mul": 1.0,
		"intel_mul": 1.0,
		"harasser_chance": 0.0,
		"role_mul": {},
		"add_lanes": [],
	}
	for mod in profile.get("mods", []):
		var op: String = mod.get("op", "mul")
		var val: float = float(mod.get("value", 1.0))
		match str(mod.get("dim", "")):
			Defs.DIM_SPAWN_CADENCE:
				h.cadence_mul *= val
			Defs.DIM_SPAWN_COUNT:
				h.count_mul *= val
			Defs.DIM_AGGRESSION:
				h.aggression_mul *= val
			Defs.DIM_HAZARD_RATE:
				h.hazard_mul *= val
			Defs.DIM_INTEL_QUALITY:
				h.intel_mul *= val
			Defs.DIM_HARASSER_CHANCE:
				h.harasser_chance += val
			Defs.DIM_LANES:
				if op == "add_lane" and not h.add_lanes.has(str(mod.value)):
					h.add_lanes.append(str(mod.value))
			Defs.DIM_ROLE_WEIGHT:
				var role := str(mod.get("role", ""))
				if role != "":
					h.role_mul[role] = h.role_mul.get(role, 1.0) * val
	return h


static func plan_wave(wave: Dictionary, profile: Dictionary, seed_val: int,
		start_step: int, replan_counter: int) -> Dictionary:
	var h := effective_hooks(profile)
	var rng := RandomNumberGenerator.new()
	rng.seed = hash([seed_val, int(wave.index), replan_counter])

	var lanes: Array = []
	for lane in wave.lanes:
		if not lanes.has(lane):
			lanes.append(lane)
	for extra in h.add_lanes:
		if not lanes.has(extra):
			lanes.append(extra)

	var batches: Array = []
	var entries: Array = wave.get("spawn_table", [])
	for i in entries.size():
		var e: Dictionary = entries[i]
		var at := start_step + int(round(float(e.at_step) * h.cadence_mul))
		var count := maxi(1, int(round(float(e.count) * h.count_mul * h.role_mul.get(str(e.role), 1.0))))
		batches.append({
			"batch_id": _batch_id(wave.index, i, replan_counter),
			"at_step": at,
			"lane": str(e.lane),
			"role": str(e.role),
			"count": count,
		})
		if h.harasser_chance > 0.0 and rng.randf() < h.harasser_chance and lanes.size() > 0:
			batches.append({
				"batch_id": _batch_id(wave.index, i, replan_counter) + "-H",
				"at_step": at + rng.randi_range(2, 10),
				"lane": str(lanes[rng.randi_range(0, lanes.size() - 1)]),
				"role": "HARASSER",
				"count": maxi(1, int(round(count * 0.3))),
			})

	batches.sort_custom(func(a, b): return int(a.at_step) < int(b.at_step))

	var hazards: Array = []
	for hz in wave.get("hazards", []):
		hazards.append({
			"at_step": start_step + int(round(float(hz.at_step) * h.hazard_mul)),
			"hazard_id": str(hz.hazard_id),
		})

	var duration := int(round(float(wave.duration_steps)))
	var plan := {
		"wave_index": int(wave.index),
		"wave_name": str(wave.name),
		"start_step": start_step,
		"end_step": start_step + duration,
		"lanes": lanes,
		"aggression": float(wave.get("aggression", 1.0)) * h.aggression_mul,
		"intel_quality": clampf(1.0 * h.intel_mul, 0.0, 1.0),
		"cadence_mul": float(h.cadence_mul),
		"batches": batches,
		"hazards": hazards,
	}
	plan["plan_hash"] = JSON.stringify(plan, "", true).md5_text()
	return plan


## Threat preview redacted by intel_quality. Deterministic thresholds, no RNG.
static func preview_from_plan(plan: Dictionary) -> Dictionary:
	var q: float = plan.intel_quality
	var lanes: Array = plan.lanes
	var role_summary: Dictionary = {}
	for b in plan.batches:
		role_summary[b.role] = int(role_summary.get(b.role, 0)) + int(b.count)
	var detail := "FULL"
	if q <= 0.25:
		detail = "DIRECTIONS_ONLY"
		role_summary = {}
	elif q < 0.75:
		detail = "FUZZED"
		for role in role_summary.keys():
			role_summary[role] = int(round(role_summary[role] / 5.0)) * 5
	return {
		"wave_index": plan.wave_index,
		"lanes": lanes,
		"roles_estimated": role_summary,
		"intel_detail": detail,
		"intel_quality": q,
	}


static func retime_pending(plan: Dictionary, wave: Dictionary,
		new_profile: Dictionary, now_step: int) -> Dictionary:
	# Mid-wave risk changes are pressure commitments, not rerolls. Already
	# planned batch identity/role/count stay immutable. GREEDY may pull future
	# contacts earlier; switching back SAFE never pushes them later again.
	var out := plan.duplicate(true)
	var hooks := effective_hooks(new_profile)
	var old_cadence := float(plan.get("cadence_mul", 1.0))
	var committed_cadence := minf(old_cadence, float(hooks.cadence_mul))
	var ratio := committed_cadence / maxf(old_cadence, 0.001)
	var pending: Array = []
	for b_v in plan.get("batches", []):
		var b: Dictionary = (b_v as Dictionary).duplicate(true)
		var old_at := int(b.at_step)
		if old_at <= now_step:
			continue
		var delay := maxi(1, old_at - now_step)
		var candidate := now_step + maxi(1, int(round(float(delay) * ratio)))
		b.at_step = mini(old_at, candidate)
		pending.append(b)
	pending.sort_custom(func(a, b): return int(a.at_step) < int(b.at_step))

	var hazards: Array = []
	for hz_v in plan.get("hazards", []):
		var hz: Dictionary = (hz_v as Dictionary).duplicate(true)
		var old_at := int(hz.at_step)
		if old_at <= now_step:
			continue
		var delay := maxi(1, old_at - now_step)
		var candidate := now_step + maxi(1, int(round(float(delay) * ratio)))
		hz.at_step = mini(old_at, candidate)
		hazards.append(hz)

	out.batches = pending
	out.hazards = hazards
	out.aggression = float(wave.get("aggression", 1.0)) * float(hooks.aggression_mul)
	out.intel_quality = clampf(float(hooks.intel_mul), 0.0, 1.0)
	out.cadence_mul = committed_cadence
	out.plan_hash = JSON.stringify(out, "", true).md5_text()
	return out


static func pending_batches(plan: Dictionary, now_step: int) -> Array:
	return plan.batches.filter(func(b): return int(b.at_step) >= now_step)


static func due_batches(plan: Dictionary, now_step: int) -> Array:
	return plan.batches.filter(func(b): return int(b.at_step) == now_step)


static func _batch_id(wave_index: int, entry_i: int, replan_counter: int) -> String:
	var base := "W%d-B%03d" % [wave_index, entry_i]
	return base if replan_counter == 0 else "%s-R%d" % [base, replan_counter]

