	var emi := runtime != null and runtime.hazard_active("EMI_SURGE")
	var range_mul := float(runtime.hazard_value("turret_range_mul",1.0)) if runtime != null else 1.0
	for i in range(_turrets.size()):
		var turret: Dictionary = _turrets[i]
		if bool(turret.destroyed) or int(turret.carried_by) > 0:
			continue
		turret.cooldown = maxf(0.0,float(turret.cooldown)-dt)
		if not emi and int(turret.ammo)>0 and float(turret.cooldown)<=0.0:
			var is_cc := str(turret.kind)=="CC"
			var range_f := float(stats.cc_range if is_cc else stats.mg_range) * range_mul
			var target := crowd.find_nearest_enemy(turret.pos,range_f,is_cc)
			if target>=0 and crowd.world_los_clear(
				turret.pos+Vector3.UP*1.15,crowd.enemy_position(target)+Vector3.UP*0.35):
				if is_cc:
					crowd.apply_slow(target,stats.cc_slow_factor,stats.cc_slow_duration)
					crowd.apply_damage(target,int(round(stats.cc_damage)),
						_turret_nodes[turret.id],false,"cc")
					turret.cooldown=stats.cc_interval
				else:
					crowd.apply_damage(target,int(round(stats.mg_damage)),
						_turret_nodes[turret.id],false,"mg")
					turret.cooldown=stats.mg_interval
				turret.ammo=int(turret.ammo)-1
				ammo_spent.emit(1)
				_update_turret_visual(turret)
		_turrets[i]=turret
	_state_acc += dt
	if _state_acc >= 1.0/STATE_HZ:
		_state_acc=0.0
		_publish_state()


func on_mission_event(event: Dictionary) -> void:
	if not _authoritative:
		return
	var kind := str(event.get("kind",""))
	if kind == "RESUPPLY_WINDOW_OPENED" \
			and _resupply_per_intermission > 0 and not _supply_destroyed:
		_supply_reserve += _resupply_per_intermission
		resupply_received.emit(_resupply_per_intermission)
		_publish_state()
	elif kind == "WAVE_STARTED":
		var changed := false
		for peer_v in _carried_turrets.keys().duplicate():
			changed = _release_carried_turret(int(peer_v)) or changed
		if changed:
			threat_cue.emit({"kind":"turret_relocated","target":"AUTO_COMMIT"})
			_publish_state()


func _refresh_infrastructure_targets() -> void:
	if crowd == null:
		return
	var targets:Array=[]
	for turret in _turrets:
		if not bool(turret.destroyed) and int(turret.carried_by)==0:
			targets.append({"id":str(turret.id),"pos":turret.pos})
	if not _supply_destroyed:
		targets.append({"id":"SUPPLY_MAIN","pos":OperationLayout.pois().supply_point})
	crowd.configure_infrastructure_targets(targets)


func _on_infrastructure_warning(target_id:String,enemy_uid:int)->void:
	if not _authoritative:
		return
	threat_cue.emit({"kind":"harasser_lock","target":target_id,
		"enemy_uid":enemy_uid,"map_pos":_asset_pos(target_id)})


func _on_infrastructure_strike(target_id:String,damage:float,enemy_uid:int)->void:
	if not _authoritative or damage<=0.0:
		return
	threat_cue.emit({"kind":"harasser_strike","target":target_id,
		"damage":damage,"enemy_uid":enemy_uid,"map_pos":_asset_pos(target_id)})
	if target_id=="SUPPLY_MAIN":
		if _supply_destroyed:return
		_supply_hp=maxf(0.0,_supply_hp-damage)
		if _supply_hp<=0.0:
			_supply_destroyed=true
			crowd.disable_infrastructure_target(target_id)
			asset_lost.emit(target_id)
		_publish_state(); return
	var idx:=_turret_index(target_id)
	if idx<0:return
	var turret:Dictionary=_turrets[idx]
	if bool(turret.destroyed):return
	turret.hp=maxf(0.0,float(turret.hp)-damage)
	if float(turret.hp)<=0.0:
		turret.destroyed=true
		crowd.disable_infrastructure_target(target_id)
		asset_lost.emit(target_id)
	_turrets[idx]=turret
	_update_turret_visual(turret)
	_refresh_infrastructure_targets()
	_publish_state()


func _asset_pos(id:String)->Vector3:
	if id=="SUPPLY_MAIN":return OperationLayout.pois().supply_point
	var idx:=_turret_index(id)
	return _turrets[idx].pos if idx>=0 else Vector3.ZERO


func _turret_index(id:String)->int:
	for i in range(_turrets.size()):
		if str(_turrets[i].id)==id:return i
	return -1


func get_state()->Dictionary:
	return _state_dict() if _authoritative else _replicated_state.duplicate(true)


func _state_dict()->Dictionary:
	var turrets:Array=[]
	for turret in _turrets:
		turrets.append({"id":str(turret.id),"kind":str(turret.kind),
			"socket_id":str(turret.socket_id),"pos":turret.pos,
			"ammo":int(turret.ammo),"ammo_max":int(turret.ammo_max),
			"hp":float(turret.hp),"hp_max":float(turret.hp_max),
			"destroyed":bool(turret.destroyed),"carried_by":int(turret.carried_by)})
	return {"turrets":turrets,"packs":_packs.duplicate(true),
		"carried_turrets":_carried_turrets.duplicate(true),
		"supply":{"reserve":_supply_reserve,"hp":_supply_hp,
			"hp_max":_supply_max_hp,"destroyed":_supply_destroyed}}


func _publish_state()->void:
	var state:=_state_dict()
	_replicated_state=state.duplicate(true)
	if multiplayer.multiplayer_peer!=null:_receive_state.rpc(state)


func _update_turret_visual(turret:Dictionary)->void:
	var root:Node3D=_turret_nodes.get(turret.id)
	if root!=null:
		root.position=turret.pos
		root.visible=int(turret.carried_by)==0
	var label:Label3D=_turret_labels.get(turret.id)
	if label==null:return
	if bool(turret.destroyed):
		label.text="%s DESTROYED"%str(turret.kind)
	elif int(turret.carried_by)>0:
		label.text="%s MOVING"%str(turret.kind)
	else:
		label.text="%s %d/%d HP%d%%"%[str(turret.kind),int(turret.ammo),
			int(turret.ammo_max),int(100.0*float(turret.hp)/maxf(float(turret.hp_max),1.0))]


func _unhandled_input(event:InputEvent)->void:
	if not event is InputEventKey or not event.pressed or event.echo:return
	if event.keycode==KEY_F:
		if multiplayer.is_server():_host_supply_interact(multiplayer.get_unique_id())
		else:_request_supply_interact.rpc_id(1)
	elif event.keycode==KEY_R:
		if multiplayer.is_server():_host_relocate(multiplayer.get_unique_id())
		else:_request_relocate.rpc_id(1)


func _player(peer_id:int)->Node3D:
	if players_root == null:
		return null
	return players_root.get_node_or_null("Player_%d"%peer_id) as Node3D


static func relocation_allowed(phase:String)->bool:
	return phase in ["SCOUT","INTERMISSION"]


func _release_carried_turret(peer_id:int)->bool:
	var carried_id := str(_carried_turrets.get(peer_id, ""))
	if carried_id == "":
		return false
	var idx := _turret_index(carried_id)
	if idx >= 0:
		var turret: Dictionary = _turrets[idx]
		var occupied: Dictionary = {}
		for other in _turrets:
			if str(other.id) == carried_id or bool(other.destroyed) or int(other.carried_by) > 0:
				continue
			occupied[str(other.socket_id)] = true
		var chosen: Dictionary = {}
		if not occupied.has(str(turret.socket_id)):
			for socket in OperationLayout.sockets():
				if str(socket.id) == str(turret.socket_id):
					chosen = socket
					break
		if chosen.is_empty():
			var best_d := INF
			for socket in OperationLayout.sockets():
				if occupied.has(str(socket.id)):
					continue
				var turret_pos: Vector3 = turret.get("pos", Vector3.ZERO)
				var socket_pos: Vector3 = socket.get("pos", Vector3.ZERO)
				var d: float = turret_pos.distance_to(socket_pos)
				if d < best_d:
					best_d = d
					chosen = socket
		if not chosen.is_empty():
			turret.socket_id = str(chosen.id)
			turret.pos = chosen.pos
		turret.carried_by = 0
		_turrets[idx] = turret
		_update_turret_visual(turret)
	_carried_turrets.erase(peer_id)
	_refresh_infrastructure_targets()
	return true


func _recover_invalid_carriers()->void:
	var changed := false
	for peer_v in _carried_turrets.keys().duplicate():
		var peer_id := int(peer_v)
		var player := _player(peer_id)
		if player == null or bool(player.get("downed")) or bool(player.get("embarked")):
			changed = _release_carried_turret(peer_id) or changed
	if changed:
		_publish_state()


func on_peer_left(peer_id:int)->void:
	_packs.erase(peer_id)
	if _release_carried_turret(peer_id):
		_publish_state()


func _host_supply_interact(peer_id:int)->void:
	var player:=_player(peer_id)
	if player==null or bool(player.get("downed")) or bool(player.get("embarked")):return
	var carried:=int(_packs.get(peer_id,0))
	if carried>0:
		var best_i: int = -1
		var best_d: float = INTERACT_RANGE
		for i in range(_turrets.size()):
			if bool(_turrets[i].destroyed) or int(_turrets[i].carried_by)>0:continue
			var candidate: Dictionary = _turrets[i]
			var candidate_pos: Vector3 = candidate.get("pos", Vector3.ZERO)
			var d: float = player.global_position.distance_to(candidate_pos)
			if d<best_d:best_d=d;best_i=i
		if best_i>=0:
			var turret:Dictionary=_turrets[best_i]
			var delivered:=mini(int(turret.ammo_max)-int(turret.ammo),carried)
			if delivered>0:
				turret.ammo=int(turret.ammo)+delivered;carried-=delivered
				if carried>0:_packs[peer_id]=carried
				else:_packs.erase(peer_id)
				_turrets[best_i]=turret;_update_turret_visual(turret);_publish_state()
		return
	if _supply_destroyed:return
	if player.global_position.distance_to(OperationLayout.pois().supply_point)<=INTERACT_RANGE:
		var amount:=mini(int(CombatStats.ensure().pack_size),_supply_reserve)
		if amount>0:
			_supply_reserve-=amount;_packs[peer_id]=amount
			supply_trip.emit(peer_id);_publish_state()


func _host_relocate(peer_id:int)->void:
	if runtime == null or not relocation_allowed(str(runtime.get_state().get("phase", ""))):
		threat_cue.emit({"kind":"relocate_denied","reason":"INTERWAVE_ONLY"})
		return
	var player:=_player(peer_id)
	if player==null or bool(player.get("downed")) or bool(player.get("embarked")):return
	var carried_id:=str(_carried_turrets.get(peer_id,""))
	if carried_id!="":
		var occupied:Dictionary={}
		for t in _turrets:
			if int(t.carried_by)==0 and not bool(t.destroyed):occupied[str(t.socket_id)]=true
		var best_socket: Dictionary = {}
		var best_d: float = INTERACT_RANGE
		for socket in OperationLayout.sockets():
			if occupied.has(str(socket.id)):continue
			var socket_pos: Vector3 = socket.get("pos", Vector3.ZERO)
			var d: float = player.global_position.distance_to(socket_pos)
			if d<best_d:best_d=d;best_socket=socket
		if not best_socket.is_empty():
			var idx: int = _turret_index(carried_id)
			var turret: Dictionary = _turrets[idx]
			turret.socket_id=str(best_socket.id);turret.pos=best_socket.pos;turret.carried_by=0
			_turrets[idx]=turret;_carried_turrets.erase(peer_id)
			_update_turret_visual(turret);_refresh_infrastructure_targets()
			threat_cue.emit({"kind":"turret_relocated","target":carried_id,"map_pos":turret.pos})
			_publish_state()
		return
	if int(_packs.get(peer_id,0)) > 0:
		threat_cue.emit({"kind":"relocate_denied","reason":"CARRYING_AMMO"})
		return
	var best_i: int = -1
	var best_d: float = INTERACT_RANGE
	for i in range(_turrets.size()):
		var t:Dictionary=_turrets[i]
		if bool(t.destroyed) or int(t.carried_by)>0:continue
		var turret_pos: Vector3 = t.get("pos", Vector3.ZERO)
		var d: float = player.global_position.distance_to(turret_pos)
		if d<best_d:best_d=d;best_i=i
	if best_i>=0:
		var turret:Dictionary=_turrets[best_i]
		turret.carried_by=peer_id;_turrets[best_i]=turret
		_carried_turrets[peer_id]=str(turret.id)
		_update_turret_visual(turret);_refresh_infrastructure_targets();_publish_state()


@rpc("any_peer","call_remote","reliable")
func _request_supply_interact()->void:
	if multiplayer.is_server():_host_supply_interact(multiplayer.get_remote_sender_id())


@rpc("any_peer","call_remote","reliable")
func _request_relocate()->void:
	if multiplayer.is_server():_host_relocate(multiplayer.get_remote_sender_id())


@rpc("authority","call_remote","unreliable_ordered")
func _receive_state(state:Dictionary)->void:
	if multiplayer.is_server():return
	_replicated_state=state.duplicate(true)
	for remote in state.get("turrets",[]):
		var idx:=_turret_index(str(remote.get("id","")))
		if idx<0:continue
		var local:Dictionary=_turrets[idx]
		for key in ["socket_id","pos","ammo","ammo_max","hp","hp_max","destroyed","carried_by"]:
			if remote.has(key):local[key]=remote[key]
		_turrets[idx]=local;_update_turret_visual(local)
